const MONTHS_SHORT = [
	"Jan",
	"Feb",
	"Mar",
	"Apr",
	"May",
	"Jun",
	"Jul",
	"Aug",
	"Sep",
	"Oct",
	"Nov",
	"Dec",
] as const;

/**
 * Human-readable date/time for UI. Uses local calendar fields but avoids
 * `Intl`/`toLocaleString` so SSR (Node) and the browser produce the same
 * string and React hydration stays stable.
 */
export function formatMediumDateTime(iso: string): string {
	const d = new Date(iso);
	if (Number.isNaN(d.getTime())) {
		return iso;
	}
	const day = d.getDate();
	const month = MONTHS_SHORT[d.getMonth()];
	const year = d.getFullYear();
	const hours = String(d.getHours()).padStart(2, "0");
	const minutes = String(d.getMinutes()).padStart(2, "0");
	return `${day} ${month} ${year}, ${hours}:${minutes}`;
}

